export function createNight(m,ids,trans){if(ids.length!==m.count||trans.length!==ids.length*3)throw Error('light shape');return function apply(host,origin,w,h,mix){if(!Number.isFinite(mix)||mix<0||mix>1||host.length!==w*h*4)throw Error('night frame');if(mix===0)return host;for(let p=0;p<host.length;p+=4)for(let c=0;c<3;c++)host[p+c]=Math.round(host[p+c]*(1-mix*(1-m.nightTint[c])));for(let k=0;k<ids.length;k++){const x=ids[k]%1536-origin[0],y=Math.floor(ids[k]/1536)-origin[1];if(x<0||y<0||x>=w||y>=h)continue;const p=(y*w+x)*4;for(let c=0;c<3;c++)host[p+c]=Math.round(255-(255-host[p+c])*(1-mix*(1-trans[k*3+c])))}return host}}
